B.text(9, "", [
  "Қожанасыр бір күні әбден шөлдеген соң су алып ішпек болып, түнде құдыққа барады. Құдыққа қауға салып тартса, шықпайды. «Бұған не болды?» – деп, Қожанасыр үңіліп қараса, құдықтың түбінен ай көрінеді. «Ә, қауғам айға ілініп қалған екен ғой», – деп, Қожа жұлып тартып қалғанда, қауғасы шығып кетеді, өзі шалқасынан түседі. Жерге басын соғып, есеңгіреп қалған Қожанасыр әлден уақытта көзін ашса, ай аспанда тұр. Сонда Қожекең қуанып:",
  "– Не болса, о болсын, айды аспанға бір шығардым-ау! – депті."],
  "Bilim-all.kz: «Қожанасыр, ай, құдық туралы қазақша әзіл» – https://bilim-all.kz/quote/787",
  changes="Соңғы тікелей сөз жаңа жолға шығарылды; дефистер сызықшаға ауыстырылды.")

B.evid_ru.update({
  "Ал жаңа құрылғыда арнайы сенсорлар орнатылған.": "А в новом устройстве установлены специальные сенсоры.",
  "Олар жаттығу кезінде баланың тепе-теңдігін, қысым күшін және қозғалысын тіркеп, деректер жинайды.": "Во время занятия они фиксируют равновесие ребёнка, силу давления и движения и собирают данные.",
  "Құрылғы әр бағытта баяу қозғалып, баланың тепе-теңдігін жаттықтыруға көмектеседі.": "Устройство медленно движется в разные стороны и помогает тренировать равновесие ребёнка.",
  "Баланың артық салмақ қосуы тек тамақтану ерекшелігіне байланысты емес.": "Лишний вес у ребёнка связан не только с особенностями питания.",
  "Бала күніне 4–5 рет, тамақтану аралығы 3,5–4 сағат болатындай тамақтануы қажет.": "Ребёнок должен есть 4–5 раз в день с перерывами между приёмами пищи 3,5–4 часа.",
  "Алматыда ер адам Сайран су қоймасына түсіп кетіп, өздігінен шыға алмай қалған күшікті құтқарып қалды.": "В Алматы мужчина спас щенка, который упал в водохранилище Сайран и не мог сам выбраться.",
  "Ер адам судағы күшікті аман алып шығып, оның өмірін сақтап қалды.": "Мужчина вытащил щенка из воды невредимым и спас ему жизнь.",
  "Ол күшіктің қиын жағдайда қалғанын көріп, бірден көмекке ұмтылған.": "Увидев, что щенок попал в беду, он сразу бросился на помощь.",
  "Бұл сәтті оқиға куәгері ұялы телефонына түсіріп, әлеуметтік желіде жариялаған.": "Очевидица сняла этот момент на мобильный телефон и опубликовала в социальной сети.",
  "Сол сәтте жақын маңда кішкентай қызымен серуендеп жүрген ер адам болған.": "В этот момент неподалёку гулял мужчина с маленькой дочкой.",
  "Ересектері су өсімдіктерімен, кейде судағы омыртқасыз жәндіктермен, ал балапандары су жәндіктерімен қоректенеді.": "Взрослые питаются водными растениями, иногда водными беспозвоночными, а птенцы – водными насекомыми.",
  "Аққуды қазақ халқы ежелден қастерлеп, бақыттың бастамасы, жақсылықтың жаршысы, пәктіктің, сұлулықтың белгісі деп есептейді, әрі киелі құс төресі санап, оған еш уақытта оқ атпайды.": "Казахский народ издавна почитает лебедя, считает его началом счастья, вестником добра, символом чистоты и красоты, называет священной царь-птицей и никогда в него не стреляет.",
  "Тіршілігінің көп уақытын суда өткізеді, жақсы жүзеді, бірақ сүңги алмайды, құрлыққа сирек шығады.": "Большую часть жизни проводит на воде, хорошо плавает, но не умеет нырять, на сушу выходит редко.",
  "Қазақстанда аққудың үш түрі: сұңқылдақ аққу, сыбырлақ аққу, кіші аққу кездеседі.": "В Казахстане встречаются три вида лебедей: лебедь-кликун, лебедь-шипун и малый лебедь.",
  "Аққу – қаз тәрізділер отряды, үйрек тұқымдасының жеке туысына жататын өте сымбатты құс.": "Лебедь – очень красивая, статная птица из отряда гусеобразных, семейства утиных.",
  "Қауырсындары тығыз, әрі үлпілдек мамықты шымқай ақ түсті.": "Перья у него плотные, с нежным пухом, чисто-белого цвета.",
  "Қазір қазақшаны онлайн үйреніп жүрмін.": "Сейчас я учу казахский онлайн.",
  "Менің негізгі мамандығым – француз тілінің мұғалімі.": "Моя основная профессия – учитель французского языка.",
  "Енді екеуі Қазақстанға келуді жоспарлап отыр.": "Теперь они оба планируют приехать в Казахстан.",
  "Бельгияда жүргенде домбыраның қоңыр үніне ғашық болдым.": "Ещё в Бельгии я влюбился в мягкое звучание домбры.",
  "Менің сүйікті өлеңдерімнің бірі – «Қартайдық, қайғы ойладық, ұйқы сергек».": "Одно из моих любимых стихотворений – «Қартайдық, қайғы ойладық, ұйқы сергек».",
  "– Төл аспабына қызыққан ұлттың тарихын, тілін білмей тұрып, оның мәдениеті мен болмысын толық тану мүмкін емес деп ойлаймын.": "– Я думаю, что, не зная истории и языка народа, чьим инструментом ты увлёкся, невозможно до конца понять его культуру и характер.",
  "– Көшу туралы шешімімді айтқанымда, отбасым таңғалды.": "– Когда я сказал о решении переехать, моя семья удивилась.",
  "– Абайды оқуға не түрткі болды?": "– Что подтолкнуло вас читать Абая?",
  "– Бәрі неден басталған еді?": "– С чего всё началось?",
  "Петр Великий деген патша бір күні шіркеуде тұрғанда көп адамның артқы жағында үңіліп патшаға қарап, бөркімен қалқалап қана бір нәрсені сызып тұрған балаға көзі түседі.": "Однажды царь Пётр Великий, стоя в церкви, заметил мальчика, который позади толпы всматривался в царя и, прикрываясь шапкой, что-то рисовал.",
  "– Сенің жүзіңді жазып алайын деп едім.": "– Я хотел нарисовать твоё лицо.",
  "– Оны неғылмақсың?": "– Зачем тебе это?",
  "Сол уақытқа шейін қорықпай жауап беріп тұрған бала, «сызғаныңды көрсет» дегенде, қысылайын депті.": "Мальчик, который до этого отвечал без страха, смутился, когда ему сказали «покажи, что нарисовал».",
  "Солай да болса, әлемге ақылы жеткен патша баланың талапты, зерек екенін аңғарып, оқуға бергізіп, ақырында сол бала бүкіл орыс жұртына даңқы шыққан Матвеев деген суретші болған.": "И всё же мудрый царь понял, что мальчик старательный и способный, велел отдать его учиться, и в итоге этот мальчик стал художником Матвеевым, известным всему русскому народу.",
  "– Балам, дүниедегі жаратылған жәндік-жансыздардың ешқайсысының да керексіз болып, жерде қалатыны болмайды, – деп.": "– Дочка, ничто из созданного на свете не бывает ненужным и не пропадает зря, – сказала она.",
  "Сол сөзді айтып отырғанда, қыз бала киімін жамап болып, жердегі мақтаның қиқымын терезеден лақтырып, далаға тастады:": "Пока она это говорила, девочка закончила латать одежду и выбросила в окно клочок ваты, лежавший на полу:",
  "Осылайша сөйлесіп, терезеден қарап отырса, манағы мақтаны жел көтеріп ұшырды, мұны бір торғай көріп қуып барып, мақтаны тұмсығына тістеп қана алып, ұшып кетті.": "Так они разговаривали и смотрели в окно, как вдруг ветер поднял тот клочок ваты, его увидел воробей, догнал, схватил клювом и улетел.",
  "– Манағы мақтаның қиқымын бір торғай алып кетті, оны неғылады? – деп сұрады.": "– Тот клочок ваты унёс воробей, что он с ним будет делать? – спросила она.",
  "– Балам, сол да жерде қалмайды, – деді.": "– Дочка, и он не пропадёт, – сказала она.",
  "Құндыз көбіне өзеннің тік жағасынан ін қазып, сонда паналайды.": "Выдра чаще всего роет нору в крутом берегу реки и живёт в ней.",
  "Інінің аузы су астында болады.": "Вход в нору находится под водой.",
  "Көп аулануына байланысты саны күрт азайып кеткен.": "Из-за того, что на неё много охотились, её численность резко сократилась.",
  "Орта Азия құндызы өте сирек кездесетін аң болғандықтан Қазақстанның «Қызыл кітабына» енгізілген.": "Среднеазиатская выдра – очень редкий зверь, поэтому она занесена в «Красную книгу» Казахстана.",
  "Көбіне шабақтармен, балықтармен қоректенеді.": "Питается в основном мальками и рыбой.",
  "«Ә, қауғам айға ілініп қалған екен ғой», – деп, Қожа жұлып тартып қалғанда, қауғасы шығып кетеді, өзі шалқасынан түседі.": "«А, моё ведро зацепилось за луну», – подумал Кожа, дёрнул изо всех сил, ведро выскочило, а сам он упал на спину.",
  "– Не болса, о болсын, айды аспанға бір шығардым-ау! – депті.": "– Будь что будет, зато я вернул луну на небо! – сказал он.",
  "«Бұған не болды?» – деп, Қожанасыр үңіліп қараса, құдықтың түбінен ай көрінеді.": "«Что с ним случилось?» – подумал Кожанасыр, заглянул в колодец, а на дне видна луна.",
})

